function check(source) {
  try {
    new Function(`"use strict"; ${source}`);
    return "ok";
  } catch (error) {
    return error.name;
  }
}

console.log(check("delete user.name;"));
console.log(check("delete user;"));
console.log(check("function add(a, b, a) {}"));
console.log(check("with (user) { name; }"));
